package com.fooddelivery.order.controller;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import com.fooddelivery.order.dto.OrderRequest;import com.fooddelivery.order.entity.CustomerOrder;import com.fooddelivery.order.service.OrderService;@RestController @RequestMapping("/api/orders")public class OrderController{private final OrderService s;public OrderController(OrderService s){this.s=s;}@PostMapping public ResponseEntity<CustomerOrder> create(@RequestBody OrderRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(q));}@GetMapping("/user/{userId}")public List<CustomerOrder> byUser(@PathVariable Long userId){return s.byUser(userId);}@GetMapping("/{id}")public CustomerOrder get(@PathVariable Long id){return s.get(id);}}
